from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(' ', '')
    output = []
    stack = []

    for c in paren_string:
        if c == '(':
            stack.append(c)
        else:
            stack.pop()
            if not stack:
                output.append(''.join(stack))
                stack = []

    return output
```

