def parse_nested_parens(paren_string: str) -> List[int]:
    paren_list = paren_string.split(' ')
    max_depths = []

    for paren_group in paren_list:
        max_depth = 0
        current_depth = 0

        for char in paren_group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        max_depths.append(max_depth)

    return max_depths
```

