def sort_third(l: list) -> list:
    third = []
    for i, v in enumerate(l):
        if i % 3 == 0:
            third.append(v)

    third.sort()

    result = []
    i = 0
    for j, v in enumerate(l):
        if j % 3 == 0:
            result.append(third[i])
            i += 1
        else:
            result.append(v)

    return result
```

