def sort_third(l: list) -> list:
    l1 = []
    l2 = []
    for i, val in enumerate(l):
        if i % 3 == 0:
            l1.append(val)
        else:
            l2.append(val)
    l1.sort()
    result = []
    l1_index = 0
    l2_index = 0
    for i in range(len(l)):
        if i % 3 == 0:
            result.append(l1[l1_index])
            l1_index += 1
        else:
            result.append(l2[l2_index])
            l2_index += 1
    return result
