    for i, x in enumerate(l):
        if i % 2 == 0:
            l_even.append(x)
    l_even.sort()
    l_new = []
    l_even_index = 0
    for i, x in enumerate(l):
        if i % 2 == 0:
            l_new.append(l_even[l_even_index])
            l_even_index += 1
        else:
            l_new.append(x)
    return l_new
