def modp(n: int, p: int) -> int:
    if n < 0 or p <= 1:
        return None
    result = 1
    base = 2 % p
    while n > 0:
        if n % 2 == 1:
            result = (result * base) % p
        n //= 2
        base = (base ** 2) % p
    return result
```

