def strange_sort_list(lst):
    if not lst:
        return []

    sorted_lst = []
    max_heap = []
    min_heap = []
    for num in lst:
        heappush(min_heap, num)
    while min_heap or max_heap:
        if not max_heap:
            num = heappop(min_heap)
            heappush(max_heap, -num)
