def numerical_letter_grade(grades):
    grade_table = {
        4.0: "A+",
        3.7: "A",
        3.3: "A-",
        3.0: "B+",
        2.7: "B",
        2.3: "B-",
        2.0: "C+",
        1.7: "C",
        1.3: "C-",
        1.0: "D+",
        0.7: "D",
        0.0: "D-",
        -1: "E",
    }
    def convert_gpa(gpa):
        if gpa == 4.0:
            return 4.0
        elif gpa > 3.7:
            return 3.7
        elif gpa > 3.3:
            return 3.3
        elif gpa > 3.0:
            return 3.0
        elif gpa > 2.7:
            return 2.7
        elif gpa > 2.3:
            return 2.3
        elif gpa > 2.0:
            return 2.0
        elif gpa > 1.7:
            return 1.7
        elif gpa > 1.3:
            return 1.3
        elif gpa > 1.0:
            return 1.0
        elif gpa > 0.7:
            return 0.7
        elif gpa > 0.0:
            return 0.0
        else:
            return -1
    return [grade_table[convert_gpa(gpa)] for gpa in grades]
