def move_one_ball(arr):
    n = len(arr)
    if n == 0:
        return True

    pivot_index = -1
    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            if pivot_index != -1:
                return False
            pivot_index = i
    if pivot_index == -1 or pivot_index == 0:
        return True

