    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    result = {}
    test_list = test.split()
    for char in test_list:
        if char not in result:
            result[char] = 1
        else:
            result[char] += 1
    max_count = max(result.values())
    return {k: v for k, v in result.items() if v == max_count}
