def sort_array(arr):
    def count_ones(num):
        count = 0
        while num:
            if num % 2 == 1:
                count += 1
            num //= 2
        return count

    def compare(a, b):
        ones_a = count_ones(a)
        ones_b = count_ones(b)
        if ones_a == ones_b:
            return a - b
        else:
            return ones_a - ones_b

    return sorted(arr, key=compare)
```

