def match_parens(lst):
    s1 = lst[0]
    s2 = lst[1]

    def is_good(s):
        count = 0
        for c in s:
            if c == '(':
                count += 1
            elif c == ')':
                count -= 1
            if count < 0:
                return False
        return count == 0

    if is_good(s1) or is_good(s2):
        return 'Yes'
    if s1 + s2 in (s2 + s1) and is_good(s1 + s2):
        return 'Yes'

    return 'No'
