import math

def minPath(grid, k):
    N = len(grid)
    distances = [[math.inf] * N for _ in range(N)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    distances[0][0] = grid[0][0]

    for length in range(1, k + 1):
        new_distances = [[math.inf] * N for _ in range(N)]
        for i in range(N):
            for j in range(N):
                for di, dj in directions:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < N and 0 <= nj < N:
                        new_distances[ni][nj] = min(new_distances[ni][nj], distances[i][j] + grid[ni][nj])
        distances = new_distances

    path = []
    i, j = 0, 0
    for _ in range(k):
        path.append(grid[i][j])
        next_i, next_j = None, None
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and distances[ni][nj] < distances[next_i][next_j]:
                next_i, next_j = ni, nj
        i, j = next_i, next_j

    return path
