def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)

    def isValid(x, y):
        return 0 <= x < n and 0 <= y < n

    def dfs(x, y, path):
        if len(path) == k:
            yield path[:]
            return

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if isValid(nx, ny):
                path.append(grid[nx][ny])
                yield from dfs(nx, ny, path)
                path.pop()

    def compare_paths(path1, path2):
        for i in range(k):
            if path1[i] < path2[i]:
                return True
            elif path1[i] > path2[i]:
                return False
        return False

    min_path = None

    for i in range(n):
        for j in range(n):
            path = [grid[i][j]]
            yield from dfs(i, j, path)
            if min_path is None or compare_paths(path, min_path):
                min_path = path[:]

    return min_path
