from functools import reduce

def simplify(x, n):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def simplify_fraction(numerator, denominator):
        divisor = gcd(int(numerator), int(denominator))
        return f"{int(numerator) // divisor}/{int(denominator) // divisor}"

    x_numerator, x_denominator = x.split("/")
    n_numerator, n_denominator = n.split("/")
    simplified_x = simplify_fraction(x_numerator, x_denominator)
    simplified_n = simplify_fraction(n_numerator, n_denominator)
    return int(simplified_x) * int(simplified_n) == int(simplified_x + "/" + simplified_n)
