def order_by_points(nums):
    def digit_sum(num):
        return sum(int(digit) for digit in str(abs(num)))

    def compare(x, y):
        sum_x = digit_sum(x)
        sum_y = digit_sum(y)
        if sum_x != sum_y:
            return sum_x - sum_y
        return nums.index(x) - nums.index(y)

    return sorted(nums, key=cmp_to_key(compare))
