    planets = ['Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune']
    index1 = planets.index(planet1) if planet1 in planets else None
    index2 = planets.index(planet2) if planet2 in planets else None

    if index1 is None or index2 is None or index1 == index2:
        return ()

    if index1 < index2:
        return tuple(planets[index1 + 1:index2])
    else:
        return tuple(planets[index2 + 1:index1])
```

